sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
(function executeRule(current, gForm, gSNC) {
    var equipType = gForm.getValue('equipment_type');

    if (equipType === 'Hardware') {
        gForm.setMandatory('hardware_item', true);
        gForm.setMandatory('software_item', false);
        gForm.setVisible('hardware_item', true);
        gForm.setVisible('software_item', false);
        gForm.clearValue('software_item');
    } else if (equipType === 'Software') {
        gForm.setMandatory('software_item', true);
        gForm.setMandatory('hardware_item', false);
        gForm.setVisible('software_item', true);
        gForm.setVisible('hardware_item', false);
        gForm.clearValue('hardware_item');
    } else {
        gForm.setMandatory('hardware_item', false);
        gForm.setMandatory('software_item', false);
        gForm.setVisible('hardware_item', false);
        gForm.setVisible('software_item', false);
        gForm.clearValue('hardware_item');
        gForm.clearValue('software_item');
    }
})(current, gForm, gSNC);

    //Type appropriate comment here, and begin script below

}
